{"implementation": "def solve(case):
    nodes = case["nodes"]
    core_distance = case["core_distance"]
    distances = case["distances"]

    # Compute mutual reachability distance for each pair:
    # mrd(u, v) = max(core_dist[u], core_dist[v], dist(u, v))
    edges = []
    for entry in distances:
        u, v, d = entry[0], entry[1], entry[2]
        mrd = max(core_distance[u], core_distance[v], d)
        edges.append((mrd, u, v))

    # Sort by weight for Kruskal's MST
    edges.sort()

    # Union-Find with path compression and union by rank
    parent = {n: n for n in nodes}
    rank = {n: 0 for n in nodes}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    mst_edges = []
    for mrd, u, v in edges:
        if union(u, v):
            mst_edges.append([u, v, mrd])

    return {"mst": mst_edges}
